const { withGradleProperties } = require('expo/config-plugins')

/**
 * Build performance settings for gradle.properties.
 *
 * These used to live directly in android/gradle.properties, but that folder is gitignored and
 * regenerated by `expo prebuild`, which silently resets it to the template defaults (-Xmx2048m,
 * no Kotlin daemon tuning) and makes local Kotlin compilation run out of memory. Keeping them
 * here makes every prebuild re-apply them.
 */
const GRADLE_PROPERTIES = [
  { key: 'org.gradle.jvmargs', value: '-Xmx8g -XX:MaxMetaspaceSize=2g' },
  { key: 'org.gradle.workers.max', value: '4' },
  { key: 'kotlin.compiler.execution.strategy', value: 'out-of-process' },
  { key: 'kotlin.daemon.jvmargs', value: '-Xmx3g -XX:MaxMetaspaceSize=1g' },
]

module.exports = function withGradleBuildSettings(config) {
  return withGradleProperties(config, (modConfig) => {
    for (const { key, value } of GRADLE_PROPERTIES) {
      modConfig.modResults = modConfig.modResults.map((property) =>
        property.type === 'property' && property.key === key
          ? { ...property, value }
          : property,
      )
      if (!modConfig.modResults.some((property) => property.type === 'property' && property.key === key)) {
        modConfig.modResults.push({ type: 'property', key, value })
      }
    }
    return modConfig
  })
}
